INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (1, 'Video-Language Understanding: A Survey from Model Architecture, Model Training, and Data Perspectives', 'Thong Nguyen, Yi Bin, Junbin Xiao, Leigang Qu, Yicong Li, Jay Zhangjie Wu, Cong-Duy Nguyen, See-Kiong Ng, Anh Tuan Luu', 2024, '10.48550/arXiv.2406.05615', 'https://arxiv.org/abs/2406.05615', 'Humans use multiple senses to comprehend the environment. Vision and language are two of the most vital senses since they allow us to easily communicate our thoughts and perceive the world around us. There has been a lot of interest in creating video-language understanding systems with human-like senses since a video-language pair can mimic both our linguistic medium and visual environment with temporal dynamics. In this survey, we review the key tasks of these systems and highlight the associated challenges. Based on the challenges, we summarize their methods from model architecture, model training, and data perspectives. We also conduct performance comparison among the methods, and discuss promising directions for future research.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (2, 'Domain Agnostic Conditional Invariant Predictions for Domain Generalization', 'Zongbin Wang, Bin Pan, Zhenwei Shi', 2024, '10.48550/arXiv.2406.05616', 'https://arxiv.org/abs/2406.05616', 'Domain generalization aims to develop a model that can perform well on unseen target domains by learning from multiple source domains. However, recent-proposed domain generalization models usually rely on domain labels, which may not be available in many real-world scenarios. To address this challenge, we propose a Discriminant Risk Minimization (DRM) theory and the corresponding algorithm to capture the invariant features without domain labels. In DRM theory, we prove that reducing the discrepancy of prediction distribution between overall source domain and any subset of it can contribute to obtaining invariant features. To apply the DRM theory, we develop an algorithm which is composed of Bayesian inference and a new penalty termed as Categorical Discriminant Risk (CDR). In Bayesian inference, we transform the output of the model into a probability distribution to align with our theoretical assumptions. We adopt sliding update approach to approximate the overall prediction distribution of the model, which enables us to obtain CDR penalty. We also indicate the effectiveness of these components in finding invariant features. We evaluate our algorithm against various domain generalization methods on multiple real-world datasets, providing empirical support for our theory.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (3, 'Physically-Consistent Modeling and Optimization of Non-local RIS-Assisted Multi-User MIMO Communication Systems', 'Dilki Wijekoon, A. Mezghani, George C. Alexandropoulos, Ekram Hossain', 2024, '10.48550/arXiv.2406.05617', 'https://arxiv.org/abs/2406.05617', 'Mutual Coupling (MC) emerges as an inherent feature in Reconfigurable Intelligent Surfaces (RISs), particularly, when they are fabricated with sub-wavelength inter-element spacing. Hence, any physically-consistent model of the RIS operation needs to accurately describe MC-induced effects. In addition, the design of the ElectroMagnetic (EM) transmit/receive radiation patterns constitutes another critical factor for efficient RIS operation. The latter two factors lead naturally to the emergence of non-local RIS structures, whose operation can be effectively described via non-diagonal phase shift matrices. In this paper, we focus on jointly optimizing MC and the radiation patterns in multi-user MIMO communication systems assisted by non-local RISs, which are modeled via the scattering parameters. We particularly present a novel problem formulation for the joint optimization of MC, radiation patterns, and the active and passive beamforming in a physically-consistent manner, considering either reflective or transmissive RIS setups. Differently from the current approaches that design the former two parameters on the fly, we present an offline optimization method which is solved for both considered RIS functionalities. Our extensive simulation results, using both parametric and geometric channel models, showcase the validity of the proposed optimization framework over benchmark schemes, indicating that improved performance is achievable without the need for optimizing MC and the radiation patterns of the RIS on the fly, which can be rather cumbersome.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (4, 'Cross Language Soccer Framework: An Open Source Framework for the RoboCup 2D Soccer Simulation', 'Nader Zare, Aref Sayareh, Alireza Sadraii, Arad Firouzkouhi, Amilcar Soares Junior', 2024, '10.48550/arXiv.2406.05621', 'https://arxiv.org/abs/2406.05621', 'RoboCup Soccer Simulation 2D (SS2D) research is hampered by the complexity of existing Cpp-based codes like Helios, Cyrus, and Gliders, which also suffer from limited integration with modern machine learning frameworks. This development paper introduces a transformative solution a gRPC-based, language-agnostic framework that seamlessly integrates with the high-performance Helios base code. This approach not only facilitates the use of diverse programming languages including CSharp, JavaScript, and Python but also maintains the computational efficiency critical for real time decision making in SS2D. By breaking down language barriers, our framework significantly enhances collaborative potential and flexibility, empowering researchers to innovate without the overhead of mastering or developing extensive base codes. We invite the global research community to leverage and contribute to the Cross Language Soccer (CLS) framework, which is openly available under the MIT License, to drive forward the capabilities of multi-agent systems in soccer simulations.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (5, 'Observation Denoising in CYRUS Soccer Simulation 2D Team For RoboCup 2024', 'Nader Zare, Aref Sayareh, Sadra Khanjari, Arad Firouzkouhi', 2024, '10.48550/arXiv.2406.05623', 'https://arxiv.org/abs/2406.05623', 'In the Soccer Simulation 2D environment, accurate observation is crucial for effective decision making. However, challenges such as partial observation and noisy data can hinder performance. To address these issues, we propose a denoising algorithm that leverages predictive modeling and intersection analysis to enhance the accuracy of observations. Our approach aims to mitigate the impact of noise and partial data, leading to improved gameplay performance. This paper presents the framework, implementation, and preliminary results of our algorithm, demonstrating its potential in refining observations in Soccer Simulation 2D. Cyrus 2D Team is using a combination of Helios, Gliders, and Cyrus base codes.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (6, 'An arbitrary order Reconstructed Discontinuous Approximation to Fourth-order Curl Problem', 'Ruo Li, Qicheng Liu, Shuhai Zhao', 2024, '10.48550/arXiv.2406.05624', 'https://arxiv.org/abs/2406.05624', 'We present an arbitrary order discontinuous Galerkin finite element method for solving the fourth-order curl problem using a reconstructed discontinuous approximation method. It is based on an arbitrarily high-order approximation space with one unknown per element in each dimension. The discrete problem is based on the symmetric IPDG method. We prove a priori error estimates under the energy norm and the L^2 norm and show numerical results to verify the theoretical analysis.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (7, 'ATLAS: Improving Lay Summarisation with Attribute-based Control', 'Zhihao Zhang, Tomas Goldsack, Carolina Scarton, Chenghua Lin', 2024, '10.48550/arXiv.2406.05625', 'https://arxiv.org/abs/2406.05625', 'Lay summarisation aims to produce summaries of scientific articles that are comprehensible to non-expert audiences. However, previous work assumes a one-size-fits-all approach, where the content and style of the produced summary are entirely dependent on the data used to train the model. In practice, audiences with different levels of expertise will have specific needs, impacting what content should appear in a lay summary and how it should be presented. Aiming to address this, we propose ATLAS, a novel abstractive summarisation approach that can control various properties that contribute to the overall"layness"of the generated summary using targeted control attributes. We evaluate ATLAS on a combination of biomedical lay summarisation datasets, where it outperforms state-of-the-art baselines using mainstream summarisation metrics. Additional analyses provided on the discriminatory power and emergent influence of our selected controllable attributes further attest to the effectiveness of our approach.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (8, 'Domain Generalization Guided by Large-Scale Pre-Trained Priors', 'Zongbin Wang, Bin Pan, Shiyu Shen, Tian-Yang Shi, Zhenwei Shi', 2024, '10.48550/arXiv.2406.05628', 'https://arxiv.org/abs/2406.05628', 'Domain generalization (DG) aims to train a model from limited source domains, allowing it to generalize to unknown target domains. Typically, DG models only employ large-scale pre-trained models during the initialization of fine-tuning. However, large-scale pre-trained models already possess the ability to resist domain shift. If we reference pre-trained models continuously during fine-tuning to maintain this ability, it could further enhance the generalization ability of the DG model. For this purpose, we introduce a new method called Fine-Tune with Large-scale pre-trained Priors (FT-LP), which incorporates the pre-trained model as a prior into the DG fine-tuning process, ensuring that the model refers to its pre-trained model at each optimization step. FT-LP comprises a theoretical framework and a simple implementation strategy. In theory, we verify the rationality of FT-LP by introducing a generalization error bound with the pre-trained priors for DG. In implementation, we utilize an encoder to simulate the model distribution, enabling the use of FT-LP when only pre-trained weights are available. In summary, we offer a new fine-tuning method for DG algorithms to utilize pre-trained models throughout the fine-tuning process. Through experiments on various datasets and DG models, our proposed method exhibits significant improvements, indicating its effectiveness.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (9, 'Separating the “Chirp” from the “Chat”: Self-supervised Visual Grounding of Sound and Language', 'M. Hamilton, A. Zisserman, John R. Hershey, W. T. Freeman', 2024, '10.48550/arXiv.2406.05629', 'https://arxiv.org/abs/2406.05629', 'We present DenseAV, a novel dual encoder grounding architecture that learns high-resolution, semantically meaningful, and audio-visual aligned features solely through watching videos. We show that DenseAV can discover the “meaning” of words and the “location” of sounds without explicit localization supervision. Furthermore, it automatically discovers and distinguishes between these two types of associations without supervision. We show that DenseAV''s localization abilities arise from a new multi-head feature aggregation operator that directly compares dense image and audio representations for contrastive learning. In contrast, many other systems that learn “global” audio and video representations cannot localize words and sound. Finally, we contribute two new datasets to improve the evaluation of AV representations through speech and sound prompted semantic segmentation. On these and other datasets we show DenseAV dramatically outperforms the prior art on speech and sound prompted semantic segmentation. DenseAV outperforms the current state-of-the-art, ImageBind, on cross-modal retrieval using fewer than half of the parameters. Project Page: https://aka.ms/denseav');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (10, 'Ctrl-V: Higher Fidelity Video Generation with Bounding-Box Controlled Object Motion', 'G. Luo, Z. Luo, Anthony Gosselin, Alexia Jolicoeur-Martineau, Christopher Pal', 2024, '10.48550/arXiv.2406.05630', 'https://arxiv.org/abs/2406.05630', 'Controllable video generation has attracted significant attention, largely due to advances in video diffusion models. In domains such as autonomous driving, it is essential to develop highly accurate predictions for object motions. This paper tackles a crucial challenge of how to exert precise control over object motion for realistic video synthesis. To accomplish this, we 1) control object movements using bounding boxes and extend this control to the renderings of 2D or 3D boxes in pixel space, 2) employ a distinct, specialized model to forecast the trajectories of object bounding boxes based on their previous and, if desired, future positions, and 3) adapt and enhance a separate video diffusion network to create video content based on these high quality trajectory forecasts. Our method, Ctrl-V, leverages modified and fine-tuned Stable Video Diffusion (SVD) models to solve both trajectory and video generation. Extensive experiments conducted on the KITTI, Virtual-KITTI 2, BDD100k, and nuScenes datasets validate the effectiveness of our approach in producing realistic and controllable video generation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (11, 'CCSI: Continual Class-Specific Impression for Data-free Class Incremental Learning', 'Sana Ayromlou, Teresa Tsang, P. Abolmaesumi, Xiaoxiao Li', 2024, '10.48550/arXiv.2406.05631', 'https://arxiv.org/abs/2406.05631', 'In real-world clinical settings, traditional deep learning-based classification methods struggle with diagnosing newly introduced disease types because they require samples from all disease classes for offline training. Class incremental learning offers a promising solution by adapting a deep network trained on specific disease classes to handle new diseases. However, catastrophic forgetting occurs, decreasing the performance of earlier classes when adapting the model to new data. Prior proposed methodologies to overcome this require perpetual storage of previous samples, posing potential practical concerns regarding privacy and storage regulations in healthcare. To this end, we propose a novel data-free class incremental learning framework that utilizes data synthesis on learned classes instead of data storage from previous classes. Our key contributions include acquiring synthetic data known as Continual Class-Specific Impression (CCSI) for previously inaccessible trained classes and presenting a methodology to effectively utilize this data for updating networks when introducing new classes. We obtain CCSI by employing data inversion over gradients of the trained classification model on previous classes starting from the mean image of each class inspired by common landmarks shared among medical images and utilizing continual normalization layers statistics as a regularizer in this pixel-wise optimization process. Subsequently, we update the network by combining the synthesized data with new class data and incorporate several losses, including an intra-domain contrastive loss to generalize the deep network trained on the synthesized data to real data, a margin loss to increase separation among previous classes and new ones, and a cosine-normalized cross-entropy loss to alleviate the adverse effects of imbalanced distributions in training data. Extensive experiments show that the proposed framework achieves state-of-the-art performance on four of the public MedMNIST datasets and in-house echocardiography cine series, with an improvement in classification accuracy of up to 51% compared to baseline data-free methods. Our code is available at https://github.com/ubc-tea/Continual-Impression-CCSI.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (12, 'Best Response Strategies for Asymmetric Sensing in Linear-Quadratic Differential Games', 'Shubham Aggarwal, Tamer Basar, Dipankar Maity', 2024, '10.48550/arXiv.2406.05632', 'https://arxiv.org/abs/2406.05632', 'In this paper, we revisit the two-player continuous-time infinite-horizon linear quadratic differential game problem, where one of the players can sample the state of the system only intermittently due to a sensing constraint while the other player can do so continuously. Under these asymmetric sensing limitations between the players, we analyze the optimal sensing and control strategies for the player at a disadvantage while the other player continues to play its security strategy. We derive an optimal sensor policy within the class of stationary randomized policies. Finally, using simulations, we show that the expected cost accrued by the first player approaches its security level as its sensing limitation is relaxed.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (13, 'Exploring Parameter-Efficient Fine-Tuning of Large Language Model on Automated Program Repair', 'Guochang Li, Chen Zhi, Jialiang Chen, Junxiao Han, Shuiguang Deng', 2024, '10.48550/arXiv.2406.05639', 'https://arxiv.org/abs/2406.05639', 'Automated Program Repair (APR) aims to fix bugs by generating patches. And existing work has demonstrated that "pre-training and fine-tuning" paradigm enables Large Language Models (LLMs) improve fixing capabilities on APR. However, existing work mainly focuses on Full-Model Fine-Tuning (FMFT) for APR and limited research has been conducted on the execution-based evaluation of Parameter-Efficient Fine-Tuning (PEFT) for APR. Comparing to FMFT, PEFT can reduce computing resource consumption without compromising performance and has been widely adopted to other software engineering tasks.To fill this gap, we enhance the existing APR dataset by employing prompt engineering to create an instruction dataset, APR-Instruction, at first. Secondly, we fine-tune four pre-trained LLMs using four different PEFT methods with APR-Instruction. The best fine-tuned model fixes 58% more bugs than the state-of-the-art LLM-based APR techniques. The results also show that (IA)3 improves the creativity of LLMs more effectively through fine-tuning and achieves the highest fixing capability compared to the other three PEFT methods. Thirdly, we explore the optimal configuration of PEFT hyperparameters, and assess the impact of instruction dataset size, showing that a larger number of parameters and a larger training dataset do not necessarily result in better performance for PEFT. Lastly, we analyze peak memory usage and trainable parameters to show the efficiency of PEFT.This work provides a comprehensive exploration of PEFT on APR and suggests potentially promising directions for extension to other software engineering downstream tasks. APR-Instruction, PEFT weights, and the fine-tuning code are publicly available as open-source resources.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (14, 'PaRa: Personalizing Text-to-Image Diffusion via Parameter Rank Reduction', 'Shangyu Chen, Zizheng Pan, Jianfei Cai, Dinh Q. Phung', 2024, '10.48550/arXiv.2406.05641', 'https://arxiv.org/abs/2406.05641', 'Personalizing a large-scale pretrained Text-to-Image (T2I) diffusion model is challenging as it typically struggles to make an appropriate trade-off between its training data distribution and the target distribution, i.e., learning a novel concept with only a few target images to achieve personalization (aligning with the personalized target) while preserving text editability (aligning with diverse text prompts). In this paper, we propose PaRa, an effective and efficient Parameter Rank Reduction approach for T2I model personalization by explicitly controlling the rank of the diffusion model parameters to restrict its initial diverse generation space into a small and well-balanced target space. Our design is motivated by the fact that taming a T2I model toward a novel concept such as a specific art style implies a small generation space. To this end, by reducing the rank of model parameters during finetuning, we can effectively constrain the space of the denoising sampling trajectories towards the target. With comprehensive experiments, we show that PaRa achieves great advantages over existing finetuning approaches on single/multi-subject generation as well as single-image editing. Notably, compared to the prevailing fine-tuning technique LoRA, PaRa achieves better parameter efficiency (2x fewer learnable parameters) and much better target image alignment.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (15, 'The Invertibility of Cellular Automata with Menory: Correcting Errors and New Conclusions', 'Chen Wang, Xiangxin Deng, Chao Wang', 2024, '10.48550/arXiv.2406.05642', 'https://arxiv.org/abs/2406.05642', 'Cellular automata with memory (CAM) are widely used in fields such as image processing, pattern recognition, simulation, and cryptography. The invertibility of CAM is generally considered to be chaotic. Paper [Invertible behavior in elementary cellular automata with memory, Juan C. Seck-Tuoh-Mora et al., Information Sciences, 2012] presented necessary and sufficient conditions for the invertibility of elementary CAM, but it contains a critical error: it classifies identity CAM as non-invertible, whereas identity CAM is undoubtedly invertible. By integrating Amoroso''s algorithm and cycle graphs, we provide the correct necessary and sufficient conditions for the invertibility of one-dimensional CAM. Additionally, we link CAM to a specific type of cellular automaton that is isomorphic to CAM, behaves identically, and has easily determinable invertibility. This makes it a promising alternative tool for CAM applications.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (16, 'How Alignment and Jailbreak Work: Explain LLM Safety through Intermediate Hidden States', 'Zhenhong Zhou, Haiyang Yu, Xinghua Zhang, Rongwu Xu, Fei Huang, Yongbin Li', 2024, '10.48550/arXiv.2406.05644', 'https://arxiv.org/abs/2406.05644', 'Large language models (LLMs) rely on safety alignment to avoid responding to malicious user inputs. Unfortunately, jailbreak can circumvent safety guardrails, resulting in LLMs generating harmful content and raising concerns about LLM safety. Due to language models with intensive parameters often regarded as black boxes, the mechanisms of alignment and jailbreak are challenging to elucidate. In this paper, we employ weak classifiers to explain LLM safety through the intermediate hidden states. We first confirm that LLMs learn ethical concepts during pre-training rather than alignment and can identify malicious and normal inputs in the early layers. Alignment actually associates the early concepts with emotion guesses in the middle layers and then refines them to the specific reject tokens for safe generations. Jailbreak disturbs the transformation of early unethical classification into negative emotions. We conduct experiments on models from 7B to 70B across various model families to prove our conclusion. Overall, our paper indicates the intrinsical mechanism of LLM safety and how jailbreaks circumvent safety guardrails, offering a new perspective on LLM safety and reducing concerns. Our code is available at https://github.com/ydyjya/LLM-IHS-Explanation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (17, 'Anomaly Multi-classification in Industrial Scenarios: Transferring Few-shot Learning to a New Task', 'Jie Liu, Yao Wu, Xiaotong Luo, Zongze Wu', 2024, '10.48550/arXiv.2406.05645', 'https://arxiv.org/abs/2406.05645', 'In industrial scenarios, it is crucial not only to identify anomalous items but also to classify the type of anomaly. However, research on anomaly multi-classification remains largely unexplored. This paper proposes a novel and valuable research task called anomaly multi-classification. Given the challenges in applying few-shot learning to this task, due to limited training data and unique characteristics of anomaly images, we introduce a baseline model that combines RelationNet and PatchCore. We propose a data generation method that creates pseudo classes and a corresponding proxy task, aiming to bridge the gap in transferring few-shot learning to industrial scenarios. Furthermore, we utilize contrastive learning to improve the vanilla baseline, achieving much better performance than directly fine-tune a ResNet. Experiments conducted on MvTec AD and MvTec3D AD demonstrate that our approach shows superior performance in this novel task.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (18, 'ICU-Sepsis: A Benchmark MDP Built from Real Medical Data', 'Kartik Choudhary, Dhawal Gupta, Philip S. Thomas', 2024, '10.48550/arXiv.2406.05646', 'https://arxiv.org/abs/2406.05646', 'We present ICU-Sepsis, an environment that can be used in benchmarks for evaluating reinforcement learning (RL) algorithms. Sepsis management is a complex task that has been an important topic in applied RL research in recent years. Therefore, MDPs that model sepsis management can serve as part of a benchmark to evaluate RL algorithms on a challenging real-world problem. However, creating usable MDPs that simulate sepsis care in the ICU remains a challenge due to the complexities involved in acquiring and processing patient data. ICU-Sepsis is a lightweight environment that models personalized care of sepsis patients in the ICU. The environment is a tabular MDP that is widely compatible and is challenging even for state-of-the-art RL algorithms, making it a valuable tool for benchmarking their performance. However, we emphasize that while ICU-Sepsis provides a standardized environment for evaluating RL algorithms, it should not be used to draw conclusions that guide medical practice.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (19, 'Sustainable Wireless Networks via Reconfigurable Intelligent Surfaces (RISs): Overview of the ETSI ISG RIS', 'Ruiqi Liu, Shuang Zheng, Qingqing Wu, Yifan Jiang, Nan Zhang, Yuanwei Liu, M. Renzo, G. C. Alexandropoulos', 2024, '10.48550/arXiv.2406.05647', 'https://arxiv.org/abs/2406.05647', 'Reconfigurable intelligent surfaces (RISs) are a novel form of ultra-low power devices that are capable to increase the communication data rates as well as the cell coverage in a cost- and energy-efficient way. This is attributed to their programmable operation that enables them to dynamically manipulate the wireless propagation environment, a feature that has lately inspired numerous research investigations and applications. To pave the way to the formal standardization of RISs, the European Telecommunications Standards Institute (ETSI) launched the industry specification group (ISG) on the RIS technology in September 2021. This article provides a comprehensive overview of the status of the work conducted by the ETSI ISG RIS, covering typical deployment scenarios of reconfigurable metasurfaces, use cases and operating applications, requirements, emerging hardware architectures and operating modes, as well as the latest insights regarding future directions of RISs and the resulting smart wireless environments.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (20, 'Distributionally robust stochastic optimal control', 'Alexander Shapiro, Yan Li', 2024, '10.48550/arXiv.2406.05648', 'https://arxiv.org/abs/2406.05648', 'The main goal of this paper is to discuss the construction of distributionally robust counterparts of stochastic optimal control problems. Randomized and non-randomized policies are considered. In particular, necessary and sufficient conditions for the existence of non-randomized policies are given.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (21, 'GTR: Improving Large 3D Reconstruction Models through Geometry and Texture Refinement', 'Peiye Zhuang, Songfang Han, Chaoyang Wang, Aliaksandr Siarohin, Jiaxu Zou, Michael Vasilkovsky, V. Shakhrai, Sergey Korolev, S. Tulyakov, Hsin-Ying Lee', 2024, '10.48550/arXiv.2406.05649', 'https://arxiv.org/abs/2406.05649', 'We propose a novel approach for 3D mesh reconstruction from multi-view images. Our method takes inspiration from large reconstruction models like LRM that use a transformer-based triplane generator and a Neural Radiance Field (NeRF) model trained on multi-view images. However, in our method, we introduce several important modifications that allow us to significantly enhance 3D reconstruction quality. First of all, we examine the original LRM architecture and find several shortcomings. Subsequently, we introduce respective modifications to the LRM architecture, which lead to improved multi-view image representation and more computationally efficient training. Second, in order to improve geometry reconstruction and enable supervision at full image resolution, we extract meshes from the NeRF field in a differentiable manner and fine-tune the NeRF model through mesh rendering. These modifications allow us to achieve state-of-the-art performance on both 2D and 3D evaluation metrics, such as a PSNR of 28.67 on Google Scanned Objects (GSO) dataset. Despite these superior results, our feed-forward model still struggles to reconstruct complex textures, such as text and portraits on assets. To address this, we introduce a lightweight per-instance texture refinement procedure. This procedure fine-tunes the triplane representation and the NeRF color estimation model on the mesh surface using the input multi-view images in just 4 seconds. This refinement improves the PSNR to 29.79 and achieves faithful reconstruction of complex textures, such as text. Additionally, our approach enables various downstream applications, including text- or image-to-3D generation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (22, 'A Superalignment Framework in Autonomous Driving with Large Language Models', 'Xiangrui Kong, Thomas Braunl, M. Fahmi, Yue Wang', 2024, '10.48550/arXiv.2406.05651', 'https://arxiv.org/abs/2406.05651', 'Over the last year, significant advancements have been made in the realms of large language models (LLMs) and multi-modal large language models (MLLMs), particularly in their application to autonomous driving. These models have showcased remarkable abilities in processing and interacting with complex information. In autonomous driving, LLMs and MLLMs are extensively used, requiring access to sensitive vehicle data such as precise locations, images, and road conditions. This data is transmitted to an LLM-based inference cloud for advanced analysis. However, concerns arise regarding data security, as the protection against data and privacy breaches primarily depends on the LLM’s inherent security measures, without additional scrutiny or evaluation of the LLM’s inference outputs. Despite its importance, the security aspect of LLMs in autonomous driving remains underexplored. Addressing this gap, our research introduces a novel security framework for autonomous vehicles, utilizing a multi-agent LLM approach. This framework is designed to safeguard sensitive information associated with autonomous vehicles from potential leaks, while also ensuring that LLM outputs adhere to driving regulations and align with human values. It includes mechanisms to filter out irrelevant queries and verify the safety and reliability of LLM outputs. Utilizing this framework, we evaluated the security, privacy, and cost aspects of eleven large language model-driven autonomous driving cues. Additionally, we performed QA tests on these driving prompts, which successfully demonstrated the framework’s efficacy.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (23, 'Distributed Combinatorial Optimization of Downlink User Assignment in mmWave Cell-free Massive MIMO Using Graph Neural Networks', 'Bile Peng, Bihan Guo, Karl-Ludwig Besser, Luca Kunz, Ramprasad Raghunath, Anke Schmeink, E. Jorswieck, Giuseppe Caire, H. V. Poor', 2024, '10.48550/arXiv.2406.05652', 'https://arxiv.org/abs/2406.05652', 'Millimeter wave (mmWave) cell-free massive MIMO (CF mMIMO) is a promising solution for future wireless communications. However, its optimization is non-trivial due to the challenging channel characteristics. We show that mmWave CF mMIMO optimization is largely an assignment problem between access points (APs) and users due to the high path loss of mmWave channels, the limited output power of the amplifier, and the almost orthogonal channels between users given a large number of AP antennas. The combinatorial nature of the assignment problem, the requirement for scalability, and the distributed implementation of CF mMIMO make this problem difficult. In this work, we propose an unsupervised machine learning (ML) enabled solution. In particular, a graph neural network (GNN) customized for scalability and distributed implementation is introduced. Moreover, the customized GNN architecture is hierarchically permutation-equivariant (HPE), i.e., if the APs or users of an AP are permuted, the output assignment is automatically permuted in the same way. To address this combinatorial problem, we relax it to a continuous problem, and introduce an information entropy-inspired penalty term. The training objective is then formulated using the augmented Lagrangian method (ALM). The test results show that the realized sum-rate outperforms that of the generalized serial dictatorship (GSD) algorithm and is very close to an upper bound in a small network scenario, while the upper bound is impossible to obtain in a large network scenario.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (24, 'Heart Sound Segmentation Using Deep Learning Techniques', 'Manas Madine', 2024, '10.48550/arXiv.2406.05653', 'https://arxiv.org/abs/2406.05653', 'Heart disease remains a leading cause of mortality worldwide. Auscultation, the process of listening to heart sounds, can be enhanced through computer-aided analysis using Phonocardiogram (PCG) signals. This paper presents a novel approach for heart sound segmentation and classification into S1 (LUB) and S2 (DUB) sounds. We employ FFT-based filtering, dynamic programming for event detection, and a Siamese network for robust classification. Our method demonstrates superior performance on the PASCAL heart sound dataset compared to existing approaches.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (25, 'DomainRAG: A Chinese Benchmark for Evaluating Domain-specific Retrieval-Augmented Generation', 'Shuting Wang, Jiongnan Liu, Jiehan Cheng, Yuqian Fu, Peidong Guo, Kun Fang, Yutao Zhu, Zhicheng Dou', 2024, '10.48550/arXiv.2406.05654', 'https://arxiv.org/abs/2406.05654', 'Retrieval-Augmented Generation (RAG) offers a promising solution to address various limitations of Large Language Models (LLMs), such as hallucination and difficulties in keeping up with real-time updates. This approach is particularly critical in expert and domain-specific applications where LLMs struggle to cover expert knowledge. Therefore, evaluating RAG models in such scenarios is crucial, yet current studies often rely on general knowledge sources like Wikipedia to assess the models'' abilities in solving common-sense problems. In this paper, we evaluated LLMs by RAG settings in a domain-specific context, college enrollment. We identified six required abilities for RAG models, including the ability in conversational RAG, analyzing structural information, faithfulness to external knowledge, denoising, solving time-sensitive problems, and understanding multi-document interactions. Each ability has an associated dataset with shared corpora to evaluate the RAG models'' performance. We evaluated popular LLMs such as Llama, Baichuan, ChatGLM, and GPT models. Experimental results indicate that existing closed-book LLMs struggle with domain-specific questions, highlighting the need for RAG models to solve expert problems. Moreover, there is room for RAG models to improve their abilities in comprehending conversational history, analyzing structural information, denoising, processing multi-document interactions, and faithfulness in expert knowledge. We expect future studies could solve these problems better.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (26, 'Visual Prompt Tuning in Null Space for Continual Learning', 'Yue Lu, Shizhou Zhang, De Cheng, Yinghui Xing, Nannan Wang, Peng Wang, Yanning Zhang', 2024, '10.48550/arXiv.2406.05658', 'https://arxiv.org/abs/2406.05658', 'Existing prompt-tuning methods have demonstrated impressive performances in continual learning (CL), by selecting and updating relevant prompts in the vision-transformer models. On the contrary, this paper aims to learn each task by tuning the prompts in the direction orthogonal to the subspace spanned by previous tasks'' features, so as to ensure no interference on tasks that have been learned to overcome catastrophic forgetting in CL. However, different from the orthogonal projection in the traditional CNN architecture, the prompt gradient orthogonal projection in the ViT architecture shows completely different and greater challenges, i.e., 1) the high-order and non-linear self-attention operation; 2) the drift of prompt distribution brought by the LayerNorm in the transformer block. Theoretically, we have finally deduced two consistency conditions to achieve the prompt gradient orthogonal projection, which provide a theoretical guarantee of eliminating interference on previously learned knowledge via the self-attention mechanism in visual prompt tuning. In practice, an effective null-space-based approximation solution has been proposed to implement the prompt gradient orthogonal projection. Extensive experimental results demonstrate the effectiveness of anti-forgetting on four class-incremental benchmarks with diverse pre-trained baseline models, and our approach achieves superior performances to state-of-the-art methods. Our code is available at https://github.com/zugexiaodui/VPTinNSforCL.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (27, 'Do LLMs Exhibit Human-Like Reasoning? Evaluating Theory of Mind in LLMs for Open-Ended Responses', 'Maryam Amirizaniani, Elias Martin, Maryna Sivachenko, A. Mashhadi, Chirag Shah', 2024, '10.48550/arXiv.2406.05659', 'https://arxiv.org/abs/2406.05659', 'Theory of Mind (ToM) reasoning entails recognizing that other individuals possess their own intentions, emotions, and thoughts, which is vital for guiding one''s own thought processes. Although large language models (LLMs) excel in tasks such as summarization, question answering, and translation, they still face challenges with ToM reasoning, especially in open-ended questions. Despite advancements, the extent to which LLMs truly understand ToM reasoning and how closely it aligns with human ToM reasoning remains inadequately explored in open-ended scenarios. Motivated by this gap, we assess the abilities of LLMs to perceive and integrate human intentions and emotions into their ToM reasoning processes within open-ended questions. Our study utilizes posts from Reddit''s ChangeMyView platform, which demands nuanced social reasoning to craft persuasive responses. Our analysis, comparing semantic similarity and lexical overlap metrics between responses generated by humans and LLMs, reveals clear disparities in ToM reasoning capabilities in open-ended questions, with even the most advanced models showing notable limitations. To enhance LLM capabilities, we implement a prompt tuning method that incorporates human intentions and emotions, resulting in improvements in ToM reasoning performance. However, despite these improvements, the enhancement still falls short of fully achieving human-like reasoning. This research highlights the deficiencies in LLMs'' social reasoning and demonstrates how integrating human intentions and emotions can boost their effectiveness.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (28, 'Injecting Undetectable Backdoors in Obfuscated Neural Networks and Language Models', 'Alkis Kalavasis, Amin Karbasi, Argyris Oikonomou, Katerina Sotiraki, Grigoris Velegkas, M. Zampetakis', 2024, '10.48550/arXiv.2406.05660', 'https://arxiv.org/abs/2406.05660', 'As ML models become increasingly complex and integral to high-stakes domains such as finance and healthcare, they also become more susceptible to sophisticated adversarial attacks. We investigate the threat posed by undetectable backdoors, as defined in Goldwasser et al. (FOCS ''22), in models developed by insidious external expert firms. When such backdoors exist, they allow the designer of the model to sell information on how to slightly perturb their input to change the outcome of the model. We develop a general strategy to plant backdoors to obfuscated neural networks, that satisfy the security properties of the celebrated notion of indistinguishability obfuscation. Applying obfuscation before releasing neural networks is a strategy that is well motivated to protect sensitive information of the external expert firm. Our method to plant backdoors ensures that even if the weights and architecture of the obfuscated model are accessible, the existence of the backdoor is still undetectable. Finally, we introduce the notion of undetectable backdoors to language models and extend our neural network backdoor attacks to such models based on the existence of steganographic functions.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (29, 'MS-HuBERT: Mitigating Pre-training and Inference Mismatch in Masked Language Modelling methods for learning Speech Representations', 'Hemant Yadav, Sunayana Sitaram, R. Shah', 2024, '10.48550/arXiv.2406.05661', 'https://arxiv.org/abs/2406.05661', 'In recent years, self-supervised pre-training methods have gained significant traction in learning high-level information from raw speech. Among these methods, HuBERT has demonstrated SOTA performance in automatic speech recognition (ASR). However, HuBERT''s performance lags behind data2vec due to disparities in pre-training strategies. In this paper, we propose (i) a Swap method to address pre-training and inference mismatch observed in HuBERT and (ii) incorporates Multicluster masked prediction loss for more effective utilization of the models capacity. The resulting method is, MS-HuBERT, an end-to-end self-supervised pre-training method for learning robust speech representations. It beats vanilla HuBERT on the ASR Librispeech benchmark on average by a 5% margin when evaluated on different finetuning splits. Additionally, we demonstrate that the learned embeddings obtained during pre-training encode essential information for improving performance of content based tasks such as ASR.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (30, 'Overcoming Catastrophic Forgetting in Zero-Shot Cross-Lingual Generation', 'Tu Vu, Aditya Barua, Brian Lester, Daniel Matthew Cer, Mohit Iyyer, Noah Constant', 2022, '10.48550/arXiv.2205.12647', 'https://arxiv.org/abs/2205.12647', 'In this paper, we explore the challenging problem of performing a generative task in a target language when labeled data is only available in English, using summarization as a case study. We assume a strict setting with no access to parallel data or machine translation and find that common transfer learning approaches struggle in this setting, as a generative multilingual model fine-tuned purely on English catastrophically forgets how to generate non-English. Given the recent rise of parameter-efficient adaptation techniques, we conduct the first investigation into how one such method, prompt tuning (Lester et al., 2021), can overcome catastrophic forgetting to enable zero-shot cross-lingual generation. Our experiments show that parameter-efficient prompt tuning provides gains over standard fine-tuning when transferring between less-related languages, e.g., from English to Thai. However, a significant gap still remains between these methods and fully-supervised baselines. To improve cross-lingual transfer further, we explore several approaches, including: (1) mixing in unlabeled multilingual data, and (2) explicitly factoring prompts into recombinable language and task components. Our approaches can provide further quality gains, suggesting that robust zero-shot cross-lingual generation is within reach.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (31, 'Fast Inference and Transfer of Compositional Task Structures for Few-shot Task Generalization', 'Sungryull Sohn, Hyunjae Woo, Jongwook Choi, lyubing qiang, Izzeddin Gur, Aleksandra Faust, Honglak Lee', 2022, '10.48550/arXiv.2205.12648', 'https://arxiv.org/abs/2205.12648', 'We tackle real-world problems with complex structures beyond the pixel-based game or simulator. We formulate it as a few-shot reinforcement learning problem where a task is characterized by a subtask graph that defines a set of subtasks and their dependencies that are unknown to the agent. Different from the previous meta-rl methods trying to directly infer the unstructured task embedding, our multi-task subtask graph inferencer (MTSGI) first infers the common high-level task structure in terms of the subtask graph from the training tasks, and use it as a prior to improve the task inference in testing. Our experiment results on 2D grid-world and complex web navigation domains show that the proposed method can learn and leverage the common underlying structure of the tasks for faster adaptation to the unseen tasks than various existing algorithms such as meta reinforcement learning, hierarchical reinforcement learning, and other heuristic agents.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (32, 'Investigating Lexical Replacements for Arabic-English Code-Switched Data Augmentation', 'Injy Hamed, Nizar Habash, Slim Abdennadher, Ngoc Thang Vu', 2022, '10.48550/arXiv.2205.12649', 'https://arxiv.org/abs/2205.12649', 'Data sparsity is a main problem hindering the development of code-switching (CS) NLP systems. In this paper, we investigate data augmentation techniques for synthesizing dialectal Arabic-English CS text. We perform lexical replacements using word-aligned parallel corpora where CS points are either randomly chosen or learnt using a sequence-to-sequence model. We compare these approaches against dictionary-based replacements. We assess the quality of generated sentences through human evaluation and evaluate the effectiveness of data augmentation on machine translation (MT), automatic speech recognition (ASR), and speech translation (ST) tasks. Results show that using a predictive model results in more natural CS sentences compared to the random approach, as reported in human judgements. In the downstream tasks, despite the random approach generating more data, both approaches perform equally (outperforming dictionary-based replacements). Overall, data augmentation achieves 34% improvement in perplexity, 5.2% relative improvement on WER for ASR task, +4.0-5.1 BLEU points on MT task, and +2.1-2.2 BLEU points on ST over a baseline trained on available data without augmentation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (33, 'Few-shot Reranking for Multi-hop QA via Language Model Prompting', 'Muhammad Khalifa, Lajanugen Logeswaran, Moontae Lee, Ho Hin Lee, Lu Wang', 2022, '10.48550/arXiv.2205.12650', 'https://arxiv.org/abs/2205.12650', 'We study few-shot reranking for multi-hop QA (MQA) with open-domain questions. To alleviate the need for a large number of labeled question-document pairs for retriever training, we propose PromptRank, which relies on language model prompting for multi-hop path reranking. PromptRank first constructs an instruction-based prompt that includes a candidate document path and then computes the relevance score between a given question and the path based on the conditional likelihood of the question given the path prompt according to a language model. PromptRank yields strong retrieval performance on HotpotQA with only 128 training examples compared to state-of-the-art methods trained on thousands of examples - 73.6 recall@10 by PromptRank vs. 77.8 by PathRetriever and 77.5 by multi-hop dense retrieval.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (34, 'Bitext Mining Using Distilled Sentence Representations for Low-Resource Languages', 'Kevin Heffernan, Onur cCelebi, Holger Schwenk', 2022, '10.48550/arXiv.2205.12654', 'https://arxiv.org/abs/2205.12654', 'Scaling multilingual representation learning beyond the hundred most frequent languages is challenging, in particular to cover the long tail of low-resource languages. A promising approach has been to train one-for-all multilingual models capable of cross-lingual transfer, but these models often suffer from insufficient capacity and interference between unrelated languages. Instead, we move away from this approach and focus on training multiple language (family) specific representations, but most prominently enable all languages to still be encoded in the same representational space. To achieve this, we focus on teacher-student training, allowing all encoders to be mutually compatible for bitext mining, and enabling fast learning of new languages. We introduce a new teacher-student training scheme which combines supervised and self-supervised training, allowing encoders to take advantage of monolingual training data, which is valuable in the low-resource setting. Our approach significantly outperforms the original LASER encoder. We study very low-resource languages and handle 50 African languages, many of which are not covered by any other model. For these languages, we train sentence encoders, mine bitexts, and validate the bitexts by training NMT systems.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (35, 'Optimizing UAV Resupply Scheduling for Heterogeneous and Persistent Aerial Service', 'Edgar Arribas, V. Cholvi, V. Mancuso', 2022, '10.48550/arXiv.2205.12656', 'https://arxiv.org/abs/2205.12656', 'With the current advances in unmanned aerial vehicle (UAV) technologies, aerial vehicles are becoming very attractive for many purposes. However, currently the bottleneck in their adoption is no longer due to architectural and protocol challenges and constraints, but rather to the limited energy that they can rely on. In this article, we design two power resupply schemes under the assumption of a fleet of homogeneous UAVs. Such schemes are designed to minimize the size of the fleet to be devoted to a persistent service (i.e., carried out at all times) of a set of aerial locations. First, we consider the case where the aerial locations to be served are equidistant from an energy supply station. In that scenario, we design a simple scheduling scheme, that we name homogeneous rotating resupply (HoRR), which we prove to be feasible and exact in the sense that it uses the minimum possible number of UAVs to guarantee the permanent coverage of the aerial service locations. Then, we extend that work for the case of nonevenly distributed aerial locations. In this new scenario, we demonstrate that the problem becomes NP-hard, and design a lightweight scheduling scheme, partitioned heterogeneous rotating resupply (PHeRR), which extends the operation of HoRR to the heterogeneous case. Through numerical analysis, we show that PHeRR provides near-exact resupply schedules.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (36, 'MAPLE-X: Latency Prediction with Explicit Microprocessor Prior Knowledge', 'Saad Abbasi, Alexander Wong, M. Shafiee', 2022, '10.48550/arXiv.2205.12660', 'https://arxiv.org/abs/2205.12660', 'Deep neural network (DNN) latency characterization is a time-consuming process and adds significant cost to Neural Architecture Search (NAS) processes when searching for efficient convolutional neural networks for embedded vision applications. DNN Latency is a hardware dependent metric and requires direct measurement or inference on target hardware. A recently introduced latency estimation technique known as MAPLE predicts DNN execution time on previously unseen hardware devices by using hardware performance counters. Leveraging these hardware counters in the form of an implicit prior, MAPLE achieves state-of-the-art performance in latency prediction. Here, we propose MAPLE-X which extends MAPLE by incorporating explicit prior knowledge of hardware devices and DNN architecture latency to better account for model stability and robustness. First, by identifying DNN architectures that exhibit a similar latency to each other, we can generate multiple virtual examples to significantly improve the accuracy over MAPLE. Secondly, the hardware specifications are used to determine the similarity between training and test hardware to emphasize training samples captured from comparable devices (domains) and encourages improved domain alignment. Experimental results using a convolution neural network NAS benchmark across different types of devices, including an Intel processor that is now used for embedded vision applications, demonstrate a 5% improvement over MAPLE and 9% over HELP. Furthermore, we include ablation studies to independently assess the benefits of virtual examples and hardware-based sample importance.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (37, 'Estimates of the size of the domain of the implicit function theorem: a mapping degree-based approach', 'Ashutosh Jindal, D. Chatterjee, R. Banavar', 2022, '10.48550/arXiv.2205.12661', 'https://arxiv.org/abs/2205.12661', 'In this article, we present explicit estimates of size of the domain on which the implicit function theorem and the inverse function theorem are valid. For maps that are twice continuously differentiable, these estimates depend upon the magnitude of the first-order derivatives evaluated at the point of interest, and a bound on the second-order derivatives over a region of interest. One of the key contributions of this article is that the estimates presented require minimal numerical computation. In particular, these estimates are arrived at without any intermediate optimization procedures. We then present three applications in optimization and systems and control theory where the computation of such bounds turns out to be important. First, in electrical networks, the power flow operations can be written as quadratically constrained quadratic programs, and we utilize our bounds to compute the size of permissible power variations to ensure stable operations of the power system network. Second, the robustness margin of positive-definite solutions to the algebraic Riccati equation (frequently encountered in control problems) subject to perturbations in the system matrices is computed with the aid of our bounds. Finally, we employ these bounds to provide quantitative estimates of the size of the domains for feedback linearization of discrete-time control systems.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (38, 'DFM: Dialogue foundation model for universal large-scale dialogue-oriented task learning', 'Zhi Chen, Jijia Bao, Lu Chen, Yuncong Liu, Da Ma, B. Chen, Mengyue Wu, Su Zhu, Xinhsuai Dong, Fujiang Ge, Qingliang Miao, Jian-Guang Lou, Kai Yu', 2022, '10.48550/arXiv.2205.12662', 'https://arxiv.org/abs/2205.12662', 'Building a universal conversational agent has been a long-standing goal of the dialogue research community. Most previous works only focus on a small set of dialogue tasks. In this work, we aim to build a unified dialogue foundation model (DFM) which can be used to solve massive diverse dialogue tasks. To achieve this goal, a large-scale well-annotated dialogue dataset with rich task diversity (DialogZoo) is collected. We introduce a framework to unify all dialogue tasks and propose novel auxiliary self-supervised tasks to achieve stable training of DFM on the highly diverse large scale DialogZoo corpus. Experiments show that, compared with models of the same size, DFM can achieve state-of-the-art or competitive performance on very rich cross-domain downstream dialogue tasks. This demonstrates that DFM largely extends the ability of unified dialogue pre-trained model.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (39, 'QAMPARI: A Benchmark for Open-domain Questions with Many Answers', 'S. Amouyal, Tomer Wolfson, Ohad Rubin, Ori Yoran, Jonathan Herzig, Jonathan Berant', 2022, '10.48550/arXiv.2205.12665', 'https://arxiv.org/abs/2205.12665', 'Existing benchmarks for open-domain question answering (ODQA) typically focus on questions whose answers are all in a single paragraph. By contrast, many natural questions, such as “What players were drafted by the Brooklyn Nets?” have a long list of answers extracted from multiple paragraphs. Answering such questions requires retrieving and reading many passages from a large corpus. We introduce QAMPARI, an ODQA benchmark, where answers are lists of entities, spread across many paragraphs. We created QAMPARI by (a) generating questions with multiple answers from Wikipedia’s knowledge graph and tables, (b) automatically pairing answers with supporting evidence in Wikipedia paragraphs, and (c) manually paraphrasing questions and validating each answer. Across a wide range of ODQA models, we find that QAMPARI is challenging in terms of both passage retrieval and answer generation, with models reaching an F1 score of 32.8 at best. We view QAMPARI as a valuable resource for ODQA research, which will aid to develop models that handle a broad range of question types, including single and multi-answer questions.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (40, 'Trilateration-Based Device-Free Sensing: Two Base Stations and One Passive IRS Are Sufficient', 'Qipeng Wang, L. Liu, Shuowen Zhang, Shuguang Cui', 2022, '10.48550/arXiv.2205.12667', 'https://arxiv.org/abs/2205.12667', 'The classic trilateration technique can localize each target based on its distances to three anchors with known coordinates. Usually, this technique requires all the anchors and targets, e.g., the satellites and the mobile phones in Global Navigation Satellite System (GNSS), to actively transmit/receive radio signals such that the delay of the one-way radio signal propagated between each anchor and each target can be measured. Excitingly, this paper will show that the trilateration technique can be generalized to the scenario where one of the three anchors and all the targets merely reflect the radio signals passively as in radar networks, even if the propagation delay between the passive IRS and the passive targets is difficult to be measured directly, and the data association issue for multi-sensor multi-target tracking arises. Specifically, we consider device-free sensing in a cellular network consisting of two base stations (BSs), one passive intelligent reflecting surface (IRS), and multiple passive targets, to realize integrated sensing and communication (ISAC). The two BSs transmit the orthogonal frequency division multiplexing (OFDM) signals in the downlink and estimate the locations of the targets based on their reflected signals via/not via the IRS. We propose an efficient trilateration-based strategy that can first estimate the distances of each target to the two BSs and the IRS and then localize the targets. Numerical results show that the considered networked sensing architecture with heterogenous anchors can outperform its counterpart with three BSs.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (41, 'Discovering Language-neutral Sub-networks in Multilingual Language Models', 'Negar Foroutan, Mohammadreza Banaei, R. Lebret, Antoine Bosselut, K. Aberer', 2022, '10.48550/arXiv.2205.12672', 'https://arxiv.org/abs/2205.12672', 'Multilingual pre-trained language models transfer remarkably well on cross-lingual downstream tasks. However, the extent to which they learn language-neutral representations (i.e., shared representations that encode similar phenomena across languages), and the effect of such representations on cross-lingual transfer performance, remain open questions.In this work, we conceptualize language neutrality of multilingual models as a function of the overlap between language-encoding sub-networks of these models. We employ the lottery ticket hypothesis to discover sub-networks that are individually optimized for various languages and tasks. Our evaluation across three distinct tasks and eleven typologically-diverse languages demonstrates that sub-networks for different languages are topologically similar (i.e., language-neutral), making them effective initializations for cross-lingual transfer with limited performance degradation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (42, 'InstructDial: Improving Zero and Few-shot Generalization in Dialogue through Instruction Tuning', 'Prakhar Gupta, Cathy Jiao, Yi-Ting Yeh, Shikib Mehri, M. Eskenazi, Jeffrey P. Bigham', 2022, '10.48550/arXiv.2205.12673', 'https://arxiv.org/abs/2205.12673', 'Instruction tuning is an emergent paradigm in NLP wherein natural language instructions are leveraged with language models to induce zero-shot performance on unseen tasks. Dialogue is an especially interesting area in which to explore instruction tuning because dialogue systems perform multiple kinds of tasks related to language (e.g., natural language understanding and generation, domain-specific interaction), yet instruction tuning has not been systematically explored for dialogue-related tasks. We introduce InstructDial, an instruction tuning framework for dialogue, which consists of a repository of 48 diverse dialogue tasks in a unified text-to-text format created from 59 openly available dialogue datasets. We explore cross-task generalization ability on models tuned on InstructDial across diverse dialogue tasks. Our analysis reveals that InstructDial enables good zero-shot performance on unseen datasets and tasks such as dialogue evaluation and intent detection, and even better performance in a few-shot setting. To ensure that models adhere to instructions, we introduce novel meta-tasks. We establish benchmark zero-shot and few-shot performance of models trained using the proposed framework on multiple dialogue tasks.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (43, 'Training Language Models with Memory Augmentation', 'Zexuan Zhong, Tao Lei, Danqi Chen', 2022, '10.48550/arXiv.2205.12674', 'https://arxiv.org/abs/2205.12674', 'Recent work has improved language models (LMs) remarkably by equipping them with a non-parametric memory component. However, most existing approaches only introduce mem-ories at testing time or represent them using a separately trained encoder, resulting in suboptimal training of the language model. In this work, we present TRIME, a novel yet simple training approach designed for training LMs with memory augmentation. Our approach uses a training objective that directly takes in-batch examples as accessible memory. We also present new methods for memory construction and data batching, which are used for adapting to different sets of memories-local, long-term, and external memory-at testing time. We evaluate TRIME on multiple language modeling and machine translation benchmarks and show that it is able to achieve significant improvements across all the settings. Concretely, TRIME reduces the perplexity from 18.70 to 15.37 on WIKITEXT-103, by effectively leveraging a large memory set from the training corpus. Compared to standard LM training, TRIME adds negligible computational overhead and is compatible with different neural architectures, making it a versatile solution for training memory-augmented LMs.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (44, 'Evaluating the Diversity, Equity, and Inclusion of NLP Technology: A Case Study for Indian Languages', 'Simran Khanuja, Sebastian Ruder, Partha P. Talukdar', 2022, '10.48550/arXiv.2205.12676', 'https://arxiv.org/abs/2205.12676', 'In order for NLP technology to be widely applicable, fair, and useful, it needs to serve a diverse set of speakers across the world’s languages, be equitable, i.e., not unduly biased towards any particular language, and be inclusive of all users, particularly in low-resource settings where compute constraints are common. In this paper, we propose an evaluation paradigm that assesses NLP technologies across all three dimensions. While diversity and inclusion have received attention in recent literature, equity is currently unexplored. We propose to address this gap using the Gini coefficient, a well-established metric used for estimating societal wealth inequality. Using our paradigm, we highlight the distressed state of current technologies for Indian (IN) languages (a linguistically large and diverse set, with a varied speaker population), across all three dimensions. To improve upon these metrics, we demonstrate the importance of region-specific choices in model building and dataset creation, and more importantly, propose a novel, generalisable approach to optimal resource allocation during fine-tuning. Finally, we discuss steps to mitigate these biases and encourage the community to employ multi-faceted evaluation when building linguistically diverse and equitable technologies.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (45, 'Language Anisotropic Cross-Lingual Model Editing', 'Yang Xu, Yutai Hou, Wanxiang Che', 2022, '10.48550/arXiv.2205.12677', 'https://arxiv.org/abs/2205.12677', 'Multilingual pre-trained language models can learn task-specific abilities or memorize facts across multiple languages but inevitably make undesired predictions with specific inputs. Under similar observation, model editing aims to post-hoc calibrate a model targeted to specific inputs with keeping the model''s raw behavior. However, existing work only studies the monolingual scenario, which lacks the cross-lingual transferability to perform editing simultaneously across languages. In this work, we focus on cross-lingual model editing. Firstly, we define the cross-lingual model editing task and corresponding metrics, where an edit in one language propagates to the others. Next, we propose a framework to naturally adapt monolingual model editing approaches to the cross-lingual scenario using parallel corpus. Further, we propose language anisotropic editing to improve cross-lingual editing by amplifying different subsets of parameters for each language. On the newly defined cross-lingual model editing task, we empirically demonstrate the failure of monolingual baselines in propagating the edit to multiple languages and the effectiveness of the proposed language anisotropic model editing. Our code is publicly available at https://github.com/franklear/LiME.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (46, 'Self-Guided Noise-Free Data Generation for Efficient Zero-Shot Learning', 'Jiahui Gao, Renjie Pi, Yong Lin, Hang Xu, Jiacheng Ye, Zhiyong Wu, Weizhong Zhang, Xiaodan Liang, Zhenguo Li, Lingpeng Kong', 2022, '10.48550/arXiv.2205.12679', 'https://arxiv.org/abs/2205.12679', 'There is a rising interest in further exploring the zero-shot learning potential of large pre-trained language models (PLMs). A new paradigm called data-generation-based zero-shot learning has achieved impressive success. In this paradigm, the synthesized data from the PLM acts as the carrier of knowledge, which is used to train a task-specific model with orders of magnitude fewer parameters than the PLM, achieving both higher performance and efficiency than prompt-based zero-shot learning methods on PLMs. The main hurdle of this approach is that the synthesized data from PLM usually contains a significant portion of low-quality samples. Fitting on such data will greatly hamper the performance of the task-specific model, making it unreliable for deployment. Previous methods remedy this issue mainly by filtering synthetic data using heuristic metrics(e.g., output confidence), or refining the data with the help of a human expert, which comes with excessive manual tuning or expensive costs. In this paper, we propose a novel noise-robust re-weighting framework SunGen to automatically construct high-quality data for zero-shot classification problems. Our framework features the ability to learn the sample weights indicating data quality without requiring any human annotation. We theoretically and empirically verify the ability of our method to help construct good-quality synthetic datasets. Notably, SunGen-LSTM yields a 9.8% relative improvement than the baseline on average accuracy across eight different established text classification tasks.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (47, 'Optimizing Test-Time Query Representations for Dense Retrieval', 'Mujeen Sung, Jungsoo Park, Jaewoo Kang, Danqi Chen, Jinhyuk Lee', 2022, '10.48550/arXiv.2205.12680', 'https://arxiv.org/abs/2205.12680', 'Recent developments of dense retrieval rely on quality representations of queries and contexts from pre-trained query and context encoders. In this paper, we introduce TOUR (Test-Time Optimization of Query Representations), which further optimizes instance-level query representations guided by signals from test-time retrieval results. We leverage a cross-encoder re-ranker to provide fine-grained pseudo labels over retrieval results and iteratively optimize query representations with gradient descent. Our theoretical analysis reveals that TOUR can be viewed as a generalization of the classical Rocchio algorithm for pseudo relevance feedback, and we present two variants that leverage pseudo-labels as hard binary or soft continuous labels. We first apply TOUR on phrase retrieval with our proposed phrase re-ranker, and also evaluate its effectiveness on passage retrieval with an off-the-shelf re-ranker. TOUR greatly improves end-to-end open-domain question answering accuracy, as well as passage retrieval performance. TOUR also consistently improves direct re-ranking by up to 2.0% while running 1.3-2.4x faster with an efficient implementation.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (48, 'TaCube: Pre-computing Data Cubes for Answering Numerical-Reasoning Questions over Tabular Data', 'Fan Zhou, Mengkang Hu, Haoyu Dong, Zhoujun Cheng, Shi Han, Dongmei Zhang', 2022, '10.48550/arXiv.2205.12682', 'https://arxiv.org/abs/2205.12682', 'Existing auto-regressive pre-trained language models (PLMs) like T5 and BART, have been well applied to table question answering by UNIFIEDSKG and TAPEX, respectively, and demonstrated state-of-the-art results on multiple benchmarks. However, auto-regressive PLMs are challenged by recent emerging numerical reasoning datasets, such as TAT-QA, due to the error-prone implicit calculation. In this paper, we present TaCube, to pre-compute aggregation/arithmetic results for the table in advance, so that they are handy and readily available for PLMs to answer numerical reasoning questions. TaCube systematically and comprehensively covers a collection of computational operations over table segments. By simply concatenating TaCube to the input sequence of PLMs, it shows significant experimental effectiveness. TaCube promotes the F1 score from 49.6% to 66.2% on TAT-QA and achieves new state-of-the-art results on WikiTQ (59.6% denotation accuracy). TaCube’s improvements on numerical reasoning cases are even more notable: on TAT-QA, TaCube promotes the exact match accuracy of BART-large by 39.6% on sum, 52.5% on average, 36.6% on substraction, and 22.2% on division. We believe that TaCube is a general and portable pre-computation solution that can be potentially integrated to various numerical reasoning frameworks');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (49, 'Ground-Truth Labels Matter: A Deeper Look into Input-Label Demonstrations', 'Junyeob Kim, Hyuhng Joon Kim, Hyunsoo Cho, Hwiyeol Jo, Sang-Woo Lee, Sang-goo Lee, Kang Min Yoo, Taeuk Kim', 2022, '10.48550/arXiv.2205.12685', 'https://arxiv.org/abs/2205.12685', 'Despite recent explosion of interests in in-context learning, the underlying mechanism and the precise impact of the quality of demonstrations remain elusive.Intuitively, ground-truth labels should have as much impact in in-context learning (ICL) as supervised learning, but recent work reported that the input-label correspondence is significantly less important than previously thought.Intrigued by this counter-intuitive observation, we re-examine the importance of ground-truth labels in in-context learning.With the introduction of two novel metrics, namely Label-Correctness Sensitivity and Ground-truth Label Effect Ratio (GLER), we were able to conduct quantifiable analysis on the impact of ground-truth label demonstrations.Through extensive analyses, we find that the correct input-label mappings can have varying impacts on the downstream in-context learning performances, depending on the experimental configuration.Through additional studies, we identify key components, such as the verbosity of prompt templates and the language model size, as the controlling factor to achieve more noise-resilient ICL.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (50, 'ProsocialDialog: A Prosocial Backbone for Conversational Agents', 'Hyunwoo Kim, Youngjae Yu, Liwei Jiang, Ximing Lu, Daniel Khashabi, Gunhee Kim, Yejin Choi, Maarten Sap', 2022, '10.48550/arXiv.2205.12688', 'https://arxiv.org/abs/2205.12688', 'Most existing dialogue systems fail to respond properly to potentially unsafe user utterances by either ignoring or passively agreeing with them. To address this issue, we introduce ProsocialDialog, the first large-scale multi-turn dialogue dataset to teach conversational agents to respond to problematic content following social norms. Covering diverse unethical, problematic, biased, and toxic situations, ProsocialDialog contains responses that encourage prosocial behavior, grounded in commonsense social rules (i.e., rules-of-thumb, RoTs). Created via a human-AI collaborative framework, ProsocialDialog consists of 58K dialogues, with 331K utterances, 160K unique RoTs, and 497K dialogue safety labels accompanied by free-form rationales.With this dataset, we introduce a dialogue safety detection module, Canary, capable of generating RoTs given conversational context, and a socially-informed dialogue agent, Prost. Empirical results show that Prost generates more socially acceptable dialogues compared to other state-of-the-art language and dialogue models in both in-domain and out-of-domain settings. Additionally, Canary effectively guides conversational agents and off-the-shelf language models to generate significantly more prosocial responses. Our work highlights the promise and importance of creating and steering conversational AI to be socially responsible.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (51, 'Large language models are few-shot clinical information extractors', 'Monica Agrawal, S. Hegselmann, Hunter Lang, Yoon Kim, D. Sontag', 2022, '10.48550/arXiv.2205.12689', 'https://arxiv.org/abs/2205.12689', 'A long-running goal of the clinical NLP community is the extraction of important variables trapped in clinical notes. However, roadblocks have included dataset shift from the general domain and a lack of public clinical corpora and annotations. In this work, we show that large language models, such as InstructGPT (Ouyang et al., 2022), perform well at zero- and few-shot information extraction from clinical text despite not being trained specifically for the clinical domain. Whereas text classification and generation performance have already been studied extensively in such models, here we additionally demonstrate how to leverage them to tackle a diverse set of NLP tasks which require more structured outputs, including span identification, token-level sequence classification, and relation extraction. Further, due to the dearth of available data to evaluate these systems, we introduce new datasets for benchmarking few-shot clinical information extraction based on a manual re-annotation of the CASI dataset (Moon et al., 2014) for new tasks. On the clinical extraction tasks we studied, the GPT-3 systems significantly outperform existing zero- and few-shot baselines.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (52, 'Understanding Natural Language in Context', 'A. Levy, E. Karpas', 2022, '10.48550/arXiv.2205.12691', 'https://arxiv.org/abs/2205.12691', 'Recent years have seen an increasing number of applications that have a natural language interface, either in the form of chatbots or via personal assistants such as Alexa (Amazon), Google Assistant, Siri (Apple), and Cortana (Microsoft). To use these applications, a basic dialog between the assistant and the human is required. While this kind of dialog exists today mainly within static robots that do not make any movement in the household space, the challenge of reasoning about the information conveyed by the environment increases significantly when dealing with robots that can move and manipulate objects in our home environment. In this paper, we focus on cognitive robots, which have some knowledge-based models of the world and operate by reasoning and planning with this model. Thus, when the robot and the human communicate, there is already some formalism they can use -- the robot’s knowledge representation formalism. In this paper we describe an approach for translating natural language directives into the robot''s formalism, allowing much more complicated household tasks to be completed. We do so by combining off-the-shelf SoTA large language models, planning tools, and the robot knowledge of the state of the world and of its own model. This results in much more accurate interpretation of directives in natural language.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (53, 'Contrastive Learning with Boosted Memorization', 'Zhihan Zhou, Jiangchao Yao, Yanfeng Wang, Bo Han, Ya Zhang', 2022, '10.48550/arXiv.2205.12693', 'https://arxiv.org/abs/2205.12693', 'Self-supervised learning has achieved a great success in the representation learning of visual and textual data. However, the current methods are mainly validated on the well-curated datasets, which do not exhibit the real-world long-tailed distribution. Recent attempts to consider self-supervised long-tailed learning are made by rebalancing in the loss perspective or the model perspective, resembling the paradigms in the supervised long-tailed learning. Nevertheless, without the aid of labels, these explorations have not shown the expected significant promise due to the limitation in tail sample discovery or the heuristic structure design. Different from previous works, we explore this direction from an alternative perspective, i.e., the data perspective, and propose a novel Boosted Contrastive Learning (BCL) method. Specifically, BCL leverages the memorization effect of deep neural networks to automatically drive the information discrepancy of the sample views in contrastive learning, which is more efficient to enhance the long-tailed learning in the label-unaware context. Extensive experiments on a range of benchmark datasets demonstrate the effectiveness of BCL over several state-of-the-art methods. Our code is available at https://github.com/MediaBrain-SJTU/BCL.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (54, 'Train Flat, Then Compress: Sharpness-Aware Minimization Learns More Compressible Models', 'Clara Na, Sanket Vaibhav Mehta, Emma Strubell', 2022, '10.48550/arXiv.2205.12694', 'https://arxiv.org/abs/2205.12694', 'Model compression by way of parameter pruning, quantization, or distillation has recently gained popularity as an approach for reducing the computational requirements of modern deep neural network models for NLP. Inspired by prior works suggesting a connection between simpler, more generalizable models and those that lie within wider loss basins, we hypothesize that optimizing for flat minima should lead to simpler parameterizations and thus more compressible models. We propose to combine sharpness-aware minimization (SAM) with various task-specific model compression methods, including iterative magnitude pruning (IMP), structured pruning with a distillation objective, and post-training dynamic quantization. Empirically, we show that optimizing for flatter minima consistently leads to greater compressibility of parameters compared to vanilla Adam when fine-tuning BERT models, with little to no loss in accuracy on the GLUE text classification and SQuAD question answering benchmarks. Moreover, SAM finds superior winning tickets during IMP that 1) are amenable to vanilla Adam optimization, and 2) transfer more effectively across tasks.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (55, 'Revisiting DocRED - Addressing the False Negative Problem in Relation Extraction', 'Qingyu Tan, Lu Xu, Lidong Bing, H. Ng, Sharifah Mahani Aljunied', 2022, '10.48550/arXiv.2205.12696', 'https://arxiv.org/abs/2205.12696', 'The DocRED dataset is one of the most popular and widely used benchmarks for document-level relation extraction (RE). It adopts a recommend-revise annotation scheme so as to have a large-scale annotated dataset. However, we find that the annotation of DocRED is incomplete, i.e., false negative samples are prevalent. We analyze the causes and effects of the overwhelming false negative problem in the DocRED dataset. To address the shortcoming, we re-annotate 4,053 documents in the DocRED dataset by adding the missed relation triples back to the original DocRED. We name our revised DocRED dataset Re-DocRED. We conduct extensive experiments with state-of-the-art neural models on both datasets, and the experimental results show that the models trained and evaluated on our Re-DocRED achieve performance improvements of around 13 F1 points. Moreover, we conduct a comprehensive analysis to identify the potential areas for further improvement.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (56, 'PLOG: Table-to-Logic Pretraining for Logical Table-to-Text Generation', 'Ao Liu, Haoyu Dong, Naoaki Okazaki, Shi Han, Dongmei Zhang', 2022, '10.48550/arXiv.2205.12697', 'https://arxiv.org/abs/2205.12697', 'Logical table-to-text generation is a task that involves generating logically faithful sentences from tables, which requires models to derive logical-level facts from table records via logical inference. It raises a new challenge on the logical-level content planning of table-to-text models. However, directly learning the logical inference knowledge from table-text pairs is very difficult for neural models because of the ambiguity of natural language and the scarcity of parallel data. Hence even large-scale pre-trained language models present low logical fidelity on logical table-to-text. In this work, we propose a Pretrained Logical Form Generator (PLOG) framework to improve generation fidelity. Specifically, PLOG is first pretrained on a table-to-logical-form generation (table-to-logic) task, then finetuned on downstream table-to-text tasks. The logical forms are formally defined with unambiguous semantics. Hence we can collect a large amount of accurate logical forms from tables without human annotation. In addition, PLOG can learn logical inference from table-logic pairs much more reliably than from table-text pairs. To evaluate our model, we further collect a controlled logical table-to-text dataset CONTLOG based on an existing dataset. On two benchmarks, LOGICNLG and CONTLOG, PLOG outperforms strong baselines by a large margin on the logical fidelity, demonstrating the effectiveness of table-to-logic pretraining.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (57, 'BITE: Textual Backdoor Attacks with Iterative Trigger Injection', 'Jun Yan, Vansh Gupta, Xiang Ren', 2022, '10.48550/arXiv.2205.12700', 'https://arxiv.org/abs/2205.12700', 'Backdoor attacks have become an emerging threat to NLP systems. By providing poisoned training data, the adversary can embed a “backdoor” into the victim model, which allows input instances satisfying certain textual patterns (e.g., containing a keyword) to be predicted as a target label of the adversary’s choice. In this paper, we demonstrate that it is possible to design a backdoor attack that is both stealthy (i.e., hard to notice) and effective (i.e., has a high attack success rate). We propose BITE, a backdoor attack that poisons the training data to establish strong correlations between the target label and a set of “trigger words”. These trigger words are iteratively identified and injected into the target-label instances through natural word-level perturbations. The poisoned training data instruct the victim model to predict the target label on inputs containing trigger words, forming the backdoor. Experiments on four text classification datasets show that our proposed attack is significantly more effective than baseline methods while maintaining decent stealthiness, raising alarm on the usage of untrusted training data. We further propose a defense method named DeBITE based on potential trigger word removal, which outperforms existing methods in defending against BITE and generalizes well to handling other backdoor attacks.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (58, 'Eliciting and Understanding Cross-task Skills with Task-level Mixture-of-Experts', 'Qinyuan Ye, Juan Zha, Xiang Ren', 2022, '10.48550/arXiv.2205.12701', 'https://arxiv.org/abs/2205.12701', 'Recent works suggest that transformer models are capable of multi-tasking on diverse NLP tasks and adapting to new tasks efficiently. However, the potential of these multi-task models may be limited as they use the same set of parameters for all tasks. In contrast, humans tackle tasks in a more flexible way, by making proper presumptions on what skills and knowledge are relevant and executing only the necessary computations. Inspired by this, we propose to use task-level mixture-of-expert models, which has a collection of transformer layers (i.e., experts) and a router component that chooses from these experts dynamically and flexibly. We find that these models help improve the average performance gain (ARG) metric by 2.6% when adapting to unseen tasks in the few-shot setting and by 5.6% in the zero-shot generalization setting. Further, we show that the learned routing decisions partly rediscover human categorization of NLP tasks -- certain experts are strongly associated with extractive tasks, some with classification tasks, and some with tasks requiring world knowledge.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (59, 'Detecting Label Errors by Using Pre-Trained Language Models', 'Derek Chong, Jenny Hong, Christopher D. Manning', 2022, '10.48550/arXiv.2205.12702', 'https://arxiv.org/abs/2205.12702', 'We show that large pre-trained language models are inherently highly capable of identifying label errors in natural language datasets: simply examining out-of-sample data points in descending order of fine-tuned task loss significantly outperforms more complex error-detection mechanisms proposed in previous work. To this end, we contribute a novel method for introducing realistic, human-originated label noise into existing crowdsourced datasets such as SNLI and TweetNLP. We show that this noise has similar properties to real, hand-verified label errors, and is harder to detect than existing synthetic noise, creating challenges for model robustness.We argue that human-originated noise is a better standard for evaluation than synthetic noise. Finally, we use crowdsourced verification to evaluate the detection of real errors on IMDB, Amazon Reviews, and Recon, and confirm that pre-trained models perform at a 9-36% higher absolute Area Under the Precision-Recall Curve than existing models.');
INSERT INTO PAPER (paper_id, title, authors, year, DOI, url, abstract) VALUES (60, 'All about unambiguous polynomial closure', 'Thomas Place, M. Zeitoun', 2022, '10.48550/arXiv.2205.12703', 'https://arxiv.org/abs/2205.12703', 'We study a standard operator on classes of languages: unambiguous polynomial closure. We prove that for every class C of regular languages satisfying mild properties, the membership problem for its unambiguous polynomial closure UPol(C) reduces to the same problem for C. We also show that unambiguous polynomial closure coincides with alternating left and right deterministic closure. Moreover, we prove that if additionally C is finite, the separation and covering problems are decidable for UPol(C). Finally, we present an overview of the generic logical characterizations of the classes built using unambiguous polynomial closure.');
