INSERT INTO PAPER_TAG (paper_id, tag_id) VALUES (60, 29);
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (1, 1, 15, 1, 71, 223, 'yellow', 'And existing work has demonstrated that "pre-training and fine-tuning" paradigm enables Large Language Models (LLMs) improve fixing capabilities on APR.', TIMESTAMP '2026-03-31 18:11:12');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (1, 2, 36, 1, 1470, 1639, 'green', 'This work provides a comprehensive exploration of PEFT on APR and suggests potentially promising directions for extension to other software engineering downstream tasks.', TIMESTAMP '2026-07-30 02:44:51');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (2, 1, 36, 1, 918, 1020, 'green', 'We conduct experiments on models from 7B to 70B across various model families to prove our conclusion.', TIMESTAMP '2026-05-17 11:28:32');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (2, 2, 36, 1, 395, 498, 'green', 'In this paper, we employ weak classifiers to explain LLM safety through the intermediate hidden states.', TIMESTAMP '2026-10-06 19:17:29');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (4, 1, 36, 1, 479, 810, 'green', 'Whereas text classification and generation performance have already been studied extensively in such models, here we additionally demonstrate how to leverage them to tackle a diverse set of NLP tasks which require more structured outputs, including span identification, token-level sequence classification, and relation extraction.', TIMESTAMP '2026-04-20 22:49:05');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (5, 1, 25, 1, 997, 1150, 'blue', 'Moreover, SAM finds superior winning tickets during IMP that 1) are amenable to vanilla Adam optimization, and 2) transfer more effectively across tasks.', TIMESTAMP '2026-05-07 18:41:56');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (5, 2, 15, 1, 213, 471, 'yellow', 'Inspired by prior works suggesting a connection between simpler, more generalizable models and those that lie within wider loss basins, we hypothesize that optimizing for flat minima should lead to simpler parameterizations and thus more compressible models.', TIMESTAMP '2026-08-08 14:37:37');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (6, 1, 36, 1, 118, 211, 'green', 'It adopts a recommend-revise annotation scheme so as to have a large-scale annotated dataset.', TIMESTAMP '2026-04-08 03:52:55');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (6, 2, 25, 1, 612, 844, 'blue', 'We conduct extensive experiments with state-of-the-art neural models on both datasets, and the experimental results show that the models trained and evaluated on our Re-DocRED achieve performance improvements of around 13 F1 points.', TIMESTAMP '2026-04-08 19:05:07');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (7, 1, 36, 1, 493, 646, 'green', 'We propose BITE, a backdoor attack that poisons the training data to establish strong correlations between the target label and a set of “trigger words”.', TIMESTAMP '2026-05-01 17:32:35');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (7, 2, 36, 1, 647, 780, 'green', 'These trigger words are iteratively identified and injected into the target-label instances through natural word-level perturbations.', TIMESTAMP '2026-05-18 00:31:32');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (7, 3, 15, 1, 781, 919, 'yellow', 'The poisoned training data instruct the victim model to predict the target label on inputs containing trigger words, forming the backdoor.', TIMESTAMP '2026-07-28 19:48:25');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (8, 1, 30, 1, 591, 737, 'green', 'To fill this gap, we enhance the existing APR dataset by employing prompt engineering to create an instruction dataset, APR-Instruction, at first.', TIMESTAMP '2026-09-16 02:29:16');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (8, 2, 30, 1, 224, 427, 'green', 'However, existing work mainly focuses on Full-Model Fine-Tuning (FMFT) for APR and limited research has been conducted on the execution-based evaluation of Parameter-Efficient Fine-Tuning (PEFT) for APR.', TIMESTAMP '2026-09-21 02:40:18');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (11, 1, 11, 1, 315, 473, 'blue', 'In autonomous driving, LLMs and MLLMs are extensively used, requiring access to sensitive vehicle data such as precise locations, images, and road conditions.', TIMESTAMP '2026-07-04 00:22:20');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (12, 1, 11, 1, 1261, 1345, 'blue', 'This results in much more accurate interpretation of directives in natural language.', TIMESTAMP '2026-07-01 22:53:34');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (12, 2, 29, 1, 935, 1108, 'green', 'In this paper we describe an approach for translating natural language directives into the robot''s formalism, allowing much more complicated household tasks to be completed.', TIMESTAMP '2026-07-08 15:32:08');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (13, 1, 6, 1, 353, 511, 'blue', 'In this work, we conceptualize language neutrality of multilingual models as a function of the overlap between language-encoding sub-networks of these models.', TIMESTAMP '2026-05-26 16:07:13');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (14, 1, 22, 1, 0, 182, 'yellow', 'Multilingual pre-trained language models can learn task-specific abilities or memorize facts across multiple languages but inevitably make undesired predictions with specific inputs.', TIMESTAMP '2026-06-18 14:05:05');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (14, 2, 17, 1, 326, 485, 'green', 'However, existing work only studies the monolingual scenario, which lacks the cross-lingual transferability to perform editing simultaneously across languages.', TIMESTAMP '2026-06-24 17:29:17');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (14, 3, 6, 1, 486, 540, 'blue', 'In this work, we focus on cross-lingual model editing.', TIMESTAMP '2026-08-03 17:15:05');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (15, 1, 17, 1, 204, 292, 'green', 'It raises a new challenge on the logical-level content planning of table-to-text models.', TIMESTAMP '2026-04-11 02:15:00');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (15, 2, 22, 1, 293, 489, 'yellow', 'However, directly learning the logical inference knowledge from table-text pairs is very difficult for neural models because of the ambiguity of natural language and the scarcity of parallel data.', TIMESTAMP '2026-04-11 21:46:21');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (15, 3, 6, 1, 596, 705, 'blue', 'In this work, we propose a Pretrained Logical Form Generator (PLOG) framework to improve generation fidelity.', TIMESTAMP '2026-04-16 16:06:43');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (16, 1, 20, 1, 1019, 1145, 'yellow', 'DenseAV outperforms the current state-of-the-art, ImageBind, on cross-modal retrieval using fewer than half of the parameters.', TIMESTAMP '2026-09-21 18:30:17');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (17, 1, 20, 1, 679, 824, 'yellow', 'Furthermore, we utilize contrastive learning to improve the vanilla baseline, achieving much better performance than directly fine-tune a ResNet.', TIMESTAMP '2026-08-23 12:06:12');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (17, 2, 20, 1, 118, 195, 'yellow', 'However, research on anomaly multi-classification remains largely unexplored.', TIMESTAMP '2026-09-15 02:06:39');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (17, 3, 20, 1, 288, 498, 'yellow', 'Given the challenges in applying few-shot learning to this task, due to limited training data and unique characteristics of anomaly images, we introduce a baseline model that combines RelationNet and PatchCore.', TIMESTAMP '2026-09-29 00:42:38');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (18, 1, 20, 1, 821, 997, 'yellow', 'Additionally, we demonstrate that the learned embeddings obtained during pre-training encode essential information for improving performance of content based tasks such as ASR.', TIMESTAMP '2026-06-23 13:39:18');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (18, 2, 20, 1, 691, 820, 'yellow', 'It beats vanilla HuBERT on the ASR Librispeech benchmark on average by a 5% margin when evaluated on different finetuning splits.', TIMESTAMP '2026-06-25 01:30:03');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (19, 1, 1, 1, 830, 1091, 'blue', 'Specifically, BCL leverages the memorization effect of deep neural networks to automatically drive the information discrepancy of the sample views in contrastive learning, which is more efficient to enhance the long-tailed learning in the label-unaware context.', TIMESTAMP '2026-08-15 10:57:01');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (19, 2, 20, 1, 459, 648, 'yellow', 'Nevertheless, without the aid of labels, these explorations have not shown the expected significant promise due to the limitation in tail sample discovery or the heuristic structure design.', TIMESTAMP '2026-08-27 16:14:52');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (19, 3, 1, 1, 743, 829, 'blue', ', the data perspective, and propose a novel Boosted Contrastive Learning (BCL) method.', TIMESTAMP '2026-09-05 10:14:58');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (20, 1, 21, 1, 978, 1044, 'blue', 'Our approach significantly outperforms the original LASER encoder.', TIMESTAMP '2026-08-23 20:46:17');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (22, 1, 26, 1, 96, 290, 'green', 'We formulate it as a few-shot reinforcement learning problem where a task is characterized by a subtask graph that defines a set of subtasks and their dependencies that are unknown to the agent.', TIMESTAMP '2026-07-21 04:33:30');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (22, 2, 2, 1, 610, 959, 'blue', 'Our experiment results on 2D grid-world and complex web navigation domains show that the proposed method can learn and leverage the common underlying structure of the tasks for faster adaptation to the unseen tasks than various existing algorithms such as meta reinforcement learning, hierarchical reinforcement learning, and other heuristic agents.', TIMESTAMP '2026-08-10 09:20:30');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (22, 3, 2, 1, 291, 609, 'blue', 'Different from the previous meta-rl methods trying to directly infer the unstructured task embedding, our multi-task subtask graph inferencer (MTSGI) first infers the common high-level task structure in terms of the subtask graph from the training tasks, and use it as a prior to improve the task inference in testing.', TIMESTAMP '2026-09-15 22:42:00');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (23, 1, 2, 1, 273, 549, 'blue', 'PromptRank first constructs an instruction-based prompt that includes a candidate document path and then computes the relevance score between a given question and the path based on the conditional likelihood of the question given the path prompt according to a language model.', TIMESTAMP '2026-06-18 14:17:43');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (23, 2, 13, 1, 79, 272, 'yellow', 'To alleviate the need for a large number of labeled question-document pairs for retriever training, we propose PromptRank, which relies on language model prompting for multi-hop path reranking.', TIMESTAMP '2026-07-28 00:10:54');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (23, 3, 13, 1, 0, 78, 'yellow', 'We study few-shot reranking for multi-hop QA (MQA) with open-domain questions.', TIMESTAMP '2026-08-24 10:38:31');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (25, 1, 31, 1, 0, 209, 'yellow', 'Over the last year, significant advancements have been made in the realms of large language models (LLMs) and multi-modal large language models (MLLMs), particularly in their application to autonomous driving.', TIMESTAMP '2026-06-27 02:35:48');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (25, 2, 8, 1, 1236, 1345, 'blue', 'It includes mechanisms to filter out irrelevant queries and verify the safety and reliability of LLM outputs.', TIMESTAMP '2026-09-23 17:25:06');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (26, 1, 10, 1, 1033, 1109, 'yellow', 'To ensure that models adhere to instructions, we introduce novel meta-tasks.', TIMESTAMP '2026-08-26 19:08:06');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (26, 2, 9, 1, 1110, 1242, 'green', 'We establish benchmark zero-shot and few-shot performance of models trained using the proposed framework on multiple dialogue tasks.', TIMESTAMP '2026-09-02 15:16:20');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (27, 1, 9, 1, 0, 238, 'green', 'Recent years have seen an increasing number of applications that have a natural language interface, either in the form of chatbots or via personal assistants such as Alexa (Amazon), Google Assistant, Siri (Apple), and Cortana (Microsoft).', TIMESTAMP '2026-08-17 14:45:58');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (28, 1, 19, 1, 79, 268, 'yellow', 'Our method takes inspiration from large reconstruction models like LRM that use a transformer-based triplane generator and a Neural Radiance Field (NeRF) model trained on multi-view images.', TIMESTAMP '2026-09-09 05:20:11');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (29, 1, 19, 1, 796, 1071, 'yellow', 'Theoretically, we have finally deduced two consistency conditions to achieve the prompt gradient orthogonal projection, which provide a theoretical guarantee of eliminating interference on previously learned knowledge via the self-attention mechanism in visual prompt tuning.', TIMESTAMP '2026-08-26 04:39:18');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (29, 2, 19, 1, 0, 177, 'yellow', 'Existing prompt-tuning methods have demonstrated impressive performances in continual learning (CL), by selecting and updating relevant prompts in the vision-transformer models.', TIMESTAMP '2026-09-26 05:02:55');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (30, 1, 4, 1, 1111, 1438, 'blue', 'We obtain CCSI by employing data inversion over gradients of the trained classification model on previous classes starting from the mean image of each class inspired by common landmarks shared among medical images and utilizing continual normalization layers statistics as a regularizer in this pixel-wise optimization process.', TIMESTAMP '2026-04-16 18:10:57');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (30, 2, 23, 1, 672, 845, 'green', 'To this end, we propose a novel data-free class incremental learning framework that utilizes data synthesis on learned classes instead of data storage from previous classes.', TIMESTAMP '2026-04-21 07:05:45');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (31, 1, 4, 1, 444, 555, 'blue', 'Our method demonstrates superior performance on the PASCAL heart sound dataset compared to existing approaches.', TIMESTAMP '2026-06-05 05:17:38');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (31, 2, 23, 1, 203, 322, 'green', 'This paper presents a novel approach for heart sound segmentation and classification into S1 (LUB) and S2 (DUB) sounds.', TIMESTAMP '2026-07-04 20:23:34');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (32, 1, 27, 1, 633, 1025, 'yellow', 'This article provides a comprehensive overview of the status of the work conducted by the ETSI ISG RIS, covering typical deployment scenarios of reconfigurable metasurfaces, use cases and operating applications, requirements, emerging hardware architectures and operating modes, as well as the latest insights regarding future directions of RISs and the resulting smart wireless environments.', TIMESTAMP '2026-07-13 01:07:05');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (32, 2, 27, 1, 211, 429, 'yellow', 'This is attributed to their programmable operation that enables them to dynamically manipulate the wireless propagation environment, a feature that has lately inspired numerous research investigations and applications.', TIMESTAMP '2026-07-16 16:45:45');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (33, 1, 27, 1, 1060, 1195, 'yellow', 'To address this combinatorial problem, we relax it to a continuous problem, and introduce an information entropy-inspired penalty term.', TIMESTAMP '2026-06-18 20:13:54');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (33, 2, 15, 1, 208, 495, 'blue', 'We show that mmWave CF mMIMO optimization is largely an assignment problem between access points (APs) and users due to the high path loss of mmWave channels, the limited output power of the amplifier, and the almost orthogonal channels between users given a large number of AP antennas.', TIMESTAMP '2026-07-01 14:21:04');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (35, 1, 6, 1, 575, 729, 'green', 'Finally, using simulations, we show that the expected cost accrued by the first player approaches its security level as its sensing limitation is relaxed.', TIMESTAMP '2026-05-04 18:33:26');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (35, 2, 1, 1, 0, 272, 'yellow', 'In this paper, we revisit the two-player continuous-time infinite-horizon linear quadratic differential game problem, where one of the players can sample the state of the system only intermittently due to a sensing constraint while the other player can do so continuously.', TIMESTAMP '2026-07-01 02:49:38');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (35, 3, 6, 1, 273, 487, 'green', 'Under these asymmetric sensing limitations between the players, we analyze the optimal sensing and control strategies for the player at a disadvantage while the other player continues to play its security strategy.', TIMESTAMP '2026-08-27 09:46:24');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (36, 1, 1, 1, 950, 1059, 'yellow', ', if the APs or users of an AP are permuted, the output assignment is automatically permuted in the same way.', TIMESTAMP '2026-05-12 06:15:38');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (36, 2, 1, 1, 657, 737, 'yellow', 'In this work, we propose an unsupervised machine learning (ML) enabled solution.', TIMESTAMP '2026-05-13 11:00:22');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (36, 3, 29, 1, 1283, 1543, 'blue', 'The test results show that the realized sum-rate outperforms that of the generalized serial dictatorship (GSD) algorithm and is very close to an upper bound in a small network scenario, while the upper bound is impossible to obtain in a large network scenario.', TIMESTAMP '2026-05-14 11:26:41');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (37, 1, 16, 1, 344, 479, 'green', 'We prove a priori error estimates under the energy norm and the L^2 norm and show numerical results to verify the theoretical analysis.', TIMESTAMP '2026-07-28 09:35:31');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (37, 2, 35, 1, 0, 174, 'yellow', 'We present an arbitrary order discontinuous Galerkin finite element method for solving the fourth-order curl problem using a reconstructed discontinuous approximation method.', TIMESTAMP '2026-08-15 14:32:39');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (37, 3, 23, 1, 175, 283, 'blue', 'It is based on an arbitrarily high-order approximation space with one unknown per element in each dimension.', TIMESTAMP '2026-09-11 08:57:04');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (38, 1, 23, 1, 272, 385, 'blue', 'We also show that unambiguous polynomial closure coincides with alternating left and right deterministic closure.', TIMESTAMP '2026-08-05 15:11:46');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (38, 2, 35, 1, 386, 502, 'yellow', 'Moreover, we prove that if additionally C is finite, the separation and covering problems are decidable for UPol(C).', TIMESTAMP '2026-09-10 02:36:15');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (39, 1, 25, 1, 62, 202, 'green', 'Auscultation, the process of listening to heart sounds, can be enhanced through computer-aided analysis using Phonocardiogram (PCG) signals.', TIMESTAMP '2026-04-30 11:30:55');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (40, 1, 7, 1, 691, 820, 'blue', 'It beats vanilla HuBERT on the ASR Librispeech benchmark on average by a 5% margin when evaluated on different finetuning splits.', TIMESTAMP '2026-08-31 01:32:10');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (41, 1, 5, 1, 1072, 1211, 'blue', 'In practice, an effective null-space-based approximation solution has been proposed to implement the prompt gradient orthogonal projection.', TIMESTAMP '2026-08-16 15:15:12');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (41, 2, 12, 1, 648, 795, 'green', ', 1) the high-order and non-linear self-attention operation; 2) the drift of prompt distribution brought by the LayerNorm in the transformer block.', TIMESTAMP '2026-08-30 06:56:29');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (41, 3, 12, 1, 178, 439, 'green', 'On the contrary, this paper aims to learn each task by tuning the prompts in the direction orthogonal to the subspace spanned by previous tasks'' features, so as to ensure no interference on tasks that have been learned to overcome catastrophic forgetting in CL.', TIMESTAMP '2026-09-17 13:32:03');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (42, 1, 12, 1, 621, 712, 'green', ', 2021), can overcome catastrophic forgetting to enable zero-shot cross-lingual generation.', TIMESTAMP '2026-08-07 02:09:44');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (42, 2, 4, 1, 892, 986, 'yellow', 'However, a significant gap still remains between these methods and fully-supervised baselines.', TIMESTAMP '2026-08-09 09:34:08');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (43, 1, 37, 1, 788, 884, 'green', 'Despite its importance, the security aspect of LLMs in autonomous driving remains underexplored.', TIMESTAMP '2026-09-23 20:42:27');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (45, 1, 11, 1, 637, 817, 'blue', 'The environment is a tabular MDP that is widely compatible and is challenging even for state-of-the-art RL algorithms, making it a valuable tool for benchmarking their performance.', TIMESTAMP '2026-08-16 13:13:21');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (45, 2, 27, 1, 233, 373, 'green', 'Therefore, MDPs that model sepsis management can serve as part of a benchmark to evaluate RL algorithms on a challenging real-world problem.', TIMESTAMP '2026-08-27 04:12:18');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (46, 1, 27, 1, 0, 135, 'green', 'Existing benchmarks for open-domain question answering (ODQA) typically focus on questions whose answers are all in a single paragraph.', TIMESTAMP '2026-09-14 03:06:37');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (46, 2, 27, 1, 942, 1122, 'green', 'We view QAMPARI as a valuable resource for ODQA research, which will aid to develop models that handle a broad range of question types, including single and multi-answer questions.', TIMESTAMP '2026-09-18 17:47:53');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (47, 1, 20, 1, 273, 549, 'blue', 'PromptRank first constructs an instruction-based prompt that includes a candidate document path and then computes the relevance score between a given question and the path based on the conditional likelihood of the question given the path prompt according to a language model.', TIMESTAMP '2026-07-09 23:01:59');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (47, 2, 19, 1, 0, 78, 'yellow', 'We study few-shot reranking for multi-hop QA (MQA) with open-domain questions.', TIMESTAMP '2026-07-15 14:58:07');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (48, 1, 19, 1, 496, 761, 'yellow', 'We created QAMPARI by (a) generating questions with multiple answers from Wikipedia’s knowledge graph and tables, (b) automatically pairing answers with supporting evidence in Wikipedia paragraphs, and (c) manually paraphrasing questions and validating each answer.', TIMESTAMP '2026-07-23 12:13:54');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (48, 2, 19, 1, 942, 1122, 'yellow', 'We view QAMPARI as a valuable resource for ODQA research, which will aid to develop models that handle a broad range of question types, including single and multi-answer questions.', TIMESTAMP '2026-07-30 18:47:45');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (49, 1, 17, 1, 79, 272, 'blue', 'To alleviate the need for a large number of labeled question-document pairs for retriever training, we propose PromptRank, which relies on language model prompting for multi-hop path reranking.', TIMESTAMP '2026-09-23 18:12:45');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (50, 1, 24, 1, 506, 746, 'yellow', 'Our theoretical analysis reveals that TOUR can be viewed as a generalization of the classical Rocchio algorithm for pseudo relevance feedback, and we present two variants that leverage pseudo-labels as hard binary or soft continuous labels.', TIMESTAMP '2026-09-11 15:43:20');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (52, 1, 22, 1, 1023, 1138, 'green', 'In addition, PLOG can learn logical inference from table-logic pairs much more reliably than from table-text pairs.', TIMESTAMP '2026-05-09 21:34:14');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (52, 2, 34, 1, 293, 489, 'yellow', 'However, directly learning the logical inference knowledge from table-text pairs is very difficult for neural models because of the ambiguity of natural language and the scarcity of parallel data.', TIMESTAMP '2026-05-18 05:42:56');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (52, 3, 22, 1, 856, 922, 'green', 'The logical forms are formally defined with unambiguous semantics.', TIMESTAMP '2026-06-17 22:29:34');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (54, 1, 2, 1, 788, 924, 'green', 'Our method, Ctrl-V, leverages modified and fine-tuned Stable Video Diffusion (SVD) models to solve both trajectory and video generation.', TIMESTAMP '2026-07-21 03:38:06');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (54, 2, 26, 1, 118, 231, 'yellow', 'In domains such as autonomous driving, it is essential to develop highly accurate predictions for object motions.', TIMESTAMP '2026-07-30 01:59:54');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (55, 1, 30, 1, 925, 1119, 'pink', 'Extensive experiments conducted on the KITTI, Virtual-KITTI 2, BDD100k, and nuScenes datasets validate the effectiveness of our approach in producing realistic and controllable video generation.', TIMESTAMP '2026-05-23 19:27:26');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (55, 2, 31, 1, 232, 352, 'blue', 'This paper tackles a crucial challenge of how to exert precise control over object motion for realistic video synthesis.', TIMESTAMP '2026-08-21 01:23:48');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (56, 1, 8, 1, 1020, 1199, 'yellow', 'With comprehensive experiments, we show that PaRa achieves great advantages over existing finetuning approaches on single/multi-subject generation as well as single-image editing.', TIMESTAMP '2026-08-03 22:10:23');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (57, 1, 7, 1, 0, 123, 'blue', 'We present ICU-Sepsis, an environment that can be used in benchmarks for evaluating reinforcement learning (RL) algorithms.', TIMESTAMP '2026-05-22 02:33:14');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (57, 2, 15, 1, 536, 636, 'green', 'ICU-Sepsis is a lightweight environment that models personalized care of sepsis patients in the ICU.', TIMESTAMP '2026-05-27 19:28:49');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (57, 3, 7, 1, 124, 232, 'blue', 'Sepsis management is a complex task that has been an important topic in applied RL research in recent years.', TIMESTAMP '2026-06-12 20:32:56');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (58, 1, 7, 1, 610, 959, 'blue', 'Our experiment results on 2D grid-world and complex web navigation domains show that the proposed method can learn and leverage the common underlying structure of the tasks for faster adaptation to the unseen tasks than various existing algorithms such as meta reinforcement learning, hierarchical reinforcement learning, and other heuristic agents.', TIMESTAMP '2026-07-16 20:19:00');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (58, 2, 14, 1, 0, 95, 'yellow', 'We tackle real-world problems with complex structures beyond the pixel-based game or simulator.', TIMESTAMP '2026-08-10 06:47:16');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (58, 3, 14, 1, 96, 290, 'yellow', 'We formulate it as a few-shot reinforcement learning problem where a task is characterized by a subtask graph that defines a set of subtasks and their dependencies that are unknown to the agent.', TIMESTAMP '2026-09-25 03:28:05');
INSERT INTO HIGHLIGHT (group_paper_id, highlight_no, user_id, page_no, start_position, end_position, color, selected_text, created_at) VALUES (59, 1, 12, 1, 450, 629, 'pink', 'In DRM theory, we prove that reducing the discrepancy of prediction distribution between overall source domain and any subset of it can contribute to obtaining invariant features.', TIMESTAMP '2026-07-13 19:16:54');
